import{_ as t,o as e,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const R=JSON.parse('{"title":"RoundRewardRecord","description":"","frontmatter":{},"headers":[],"relativePath":"api/RoundRewardRecord.md","filePath":"api/RoundRewardRecord.md","lastUpdated":1790873127000}'),r={name:"api/RoundRewardRecord.md"};function n(c,d,i,s,l,h){return e(),a("div",null,[...d[0]||(d[0]=[o(`<h1 id="roundrewardrecord" tabindex="-1">RoundRewardRecord <a class="header-anchor" href="#roundrewardrecord" aria-label="Permalink to &quot;RoundRewardRecord&quot;">​</a></h1><p>回合奖励事件记录，位于 <code>FunGame.Core.Model.Framework</code>。记录一次回合奖励的<strong>发放 / 移除 / 夺取</strong>，供回合日志与回放展示。</p><p>由队列在奖励管线各节点写入 <code>RoundRecord.RoundRewardEvents</code>（按发生顺序排列），随回合记录一并 JSON 序列化外发。相比旧的 <code>RoundRecord.RoundRewards</code>（仅一行技能汇总），它额外带上了归属方、绑定方式与键位、顺延标记与夺取对手。</p><h2 id="事件类型-roundrewardeventkind" tabindex="-1">事件类型 RoundRewardEventKind <a class="header-anchor" href="#事件类型-roundrewardeventkind" aria-label="Permalink to &quot;事件类型 RoundRewardEventKind&quot;">​</a></h2><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>Gained</code></td><td>发放（获得）</td></tr><tr><td><code>Lost</code></td><td>移除：回合结束回收、吟唱顺延清算、被打断、施法者死亡、剥夺类效果清除</td></tr><tr><td><code>Stolen</code></td><td>夺取：归属由原持有者转移给夺取者</td></tr></tbody></table><h2 id="绑定方式-roundrewardbinding" tabindex="-1">绑定方式 RoundRewardBinding <a class="header-anchor" href="#绑定方式-roundrewardbinding" aria-label="Permalink to &quot;绑定方式 RoundRewardBinding&quot;">​</a></h2><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>Round</code></td><td>回合绑定：以全局回合为键，所有角色在该回合共享</td></tr><tr><td><code>Character</code></td><td>角色绑定：以「该角色的第 X 个行动回合」为键，仅该角色命中（默认不启用）</td></tr></tbody></table><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>Kind</code></td><td><code>RoundRewardEventKind</code></td><td>事件类型（默认 <code>Gained</code>）</td></tr><tr><td><code>Binding</code></td><td><code>RoundRewardBinding</code></td><td>奖励的绑定方式</td></tr><tr><td><code>TurnKey</code></td><td><code>int</code></td><td>奖励键：回合绑定时为全局回合；角色绑定时为该角色的行动回合序号</td></tr><tr><td><code>Character</code></td><td><code>Character</code></td><td>归属角色：Gained / Lost 为奖励归属方；Stolen 为<strong>原持有者</strong></td></tr><tr><td><code>Counterpart</code></td><td><code>Character?</code></td><td>对方角色：仅 <code>Stolen</code> 有值（夺取者）</td></tr><tr><td><code>Skills</code></td><td><code>List&lt;Skill&gt;</code></td><td>涉及的奖励；夺取时为全部被夺取项</td></tr><tr><td><code>IsCarryOver</code></td><td><code>bool</code></td><td>是否为「吟唱回合顺延到结算回合」的被动奖励（仅 <code>Lost</code> 有意义）</td></tr><tr><td><code>BindingText</code></td><td><code>string</code></td><td>绑定方式与键位的中文描述（只读，如「全局回合 10」/「行动回合 3」）</td></tr></tbody></table><h2 id="文本渲染" tabindex="-1">文本渲染 <a class="header-anchor" href="#文本渲染" aria-label="Permalink to &quot;文本渲染&quot;">​</a></h2><p><code>ToString()</code> 渲染为一行日志文本，回合日志与 <a href="/api/RoundRecordRenderer.html">RoundRecordRenderer</a> 均使用它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 米理 ] 获得回合奖励（全局回合 10）：暴击强化</span></span>
<span class="line"><span>[ 米理 ] 失去回合奖励（全局回合 10）：暴击强化</span></span>
<span class="line"><span>[ 米理 ] 失去回合奖励（行动回合 3，顺延结算）：恢复光环</span></span>
<span class="line"><span>[ 阿波 ] 的回合奖励（行动回合 5）被 [ 米理 ] 夺取：暴击强化 / 恢复光环</span></span></code></pre></div><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>事件流宿主 → <a href="/api/RoundRecord.html">RoundRecord</a></li><li>奖励规则 → <a href="/guide/round-bonus.html">回合奖励</a></li><li>上下文对象 → <a href="/api/HookContext.html">RoundRewardContext</a></li></ul>`,14)])])}const p=t(r,[["render",n]]);export{R as __pageData,p as default};
